<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/database.php';
$user=require_login(); $action=$_GET['action']??'list';
try{$pdo=db();
 if($action==='member_deliveries'){
  $memberId=(int)(($user['role']??'')==='member'?$user['id']:($_GET['member_id']??0));
  if(!in_array(($user['role']??''),['member','committee','president'],true)) json_response(['status'=>'error','message'=>'คุณไม่มีสิทธิ์ดูรายการรับสินค้า'],403);
