 if($action==='list'){
  $s=$pdo->query("SELECT b.*, f.year_be, COALESCE((SELECT COUNT(*) FROM procurement_request_items pri WHERE pri.batch_id=b.id),0) request_count, COALESCE((SELECT SUM(pbi.quantity_ordered) FROM procurement_batch_items pbi WHERE pbi.batch_id=b.id),0) ordered_qty, COALESCE((SELECT SUM(pbi.quantity_received) FROM procurement_batch_items pbi WHERE pbi.batch_id=b.id),0) received_qty FROM procurement_batches b JOIN fiscal_years f ON f.id=b.fiscal_year_id ORDER BY b.id DESC");
