 }
 if($action==='eligible_requests'){
  $s=$pdo->query("SELECT r.id,r.member_id,r.amount_requested,r.created_at,m.fullname,m.username FROM requests r JOIN members m ON m.id=r.member_id WHERE r.status IN ('member_confirmed','active') AND NOT EXISTS (SELECT 1 FROM procurement_request_items pri WHERE pri.request_id=r.id) ORDER BY r.created_at ASC");
