  $n=(int)$pdo->query("SELECT COALESCE(MAX(CAST(SUBSTRING_INDEX(batch_no,'/',1) AS UNSIGNED)),0)+1 FROM procurement_batches WHERE fiscal_year_id=".$fy)->fetchColumn();$no=str_pad((string)$n,3,'0',STR_PAD_LEFT).'/'.date('Y');
  $pdo->beginTransaction();
  $s=$pdo->prepare("INSERT INTO procurement_batches(fiscal_year_id,batch_no,title,status,created_by) VALUES(?,?,?,'draft',?)");$s->execute([$fy,$no,$title,$user['id']]);$bid=(int)$pdo->lastInsertId();
  foreach($ids as $rid){$rid=(int)$rid;$q=$pdo->prepare("SELECT ri.id,ri.catalog_item_id,ri.quantity,ri.item_name_snapshot,ri.unit_snapshot,ri.line_total, r.amount_requested FROM request_items ri JOIN requests r ON r.id=ri.request_id WHERE ri.request_id=?");$q->execute([$rid]);foreach($q as $i){$p=$pdo->prepare("INSERT INTO procurement_request_items(batch_id,request_id,request_item_id,quantity_allocated) VALUES(?,?,?,?)");$p->execute([$bid,$rid,$i['id'],$i['quantity']]);$exists=$pdo->prepare("SELECT id FROM procurement_batch_items WHERE batch_id=? AND catalog_item_id=?");$exists->execute([$bid,$i['catalog_item_id']]);$eid=$exists->fetchColumn();if($eid){$pdo->prepare('UPDATE procurement_batch_items SET quantity_ordered=quantity_ordered+? WHERE id=?')->execute([$i['quantity'],$eid]);}else{$cat=$pdo->prepare('SELECT unit_price FROM catalog_items WHERE id=?');$cat->execute([$i['catalog_item_id']]);$price=(float)$cat->fetchColumn();$pdo->prepare("INSERT INTO procurement_batch_items(batch_id,catalog_item_id,item_name_snapshot,unit_snapshot,quantity_ordered,unit_price) VALUES(?,?,?,?,?,?)")->execute([$bid,$i['catalog_item_id'],$i['item_name_snapshot'],$i['unit_snapshot'],$i['quantity'],$price]);}}}
  $pdo->commit();json_response(['status'=>'success','message'=>'สร้างรอบจัดซื้อแล้ว','id'=>$bid]);
