 if($action==='detail'){$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM procurement_batches WHERE id=?');$q->execute([$id]);$batch=$q->fetch();if(!$batch)json_response(['status'=>'error','message'=>'ไม่พบรอบจัดซื้อ'],404);$q=$pdo->prepare('SELECT * FROM procurement_batch_items WHERE batch_id=? ORDER BY item_name_snapshot');$q->execute([$id]);$batch['items']=$q->fetchAll();$q=$pdo->prepare("SELECT pri.*,m.fullname,m.username,r.amount_requested FROM procurement_request_items pri JOIN requests r ON r.id=pri.request_id JOIN members m ON m.id=r.member_id WHERE pri.batch_id=? ORDER BY m.fullname");$q->execute([$id]);$batch['requests']=$q->fetchAll();json_response(['status'=>'success','data'=>$batch]);}
 if($action==='receive'){$d=json_input();$id=(int)($d['batch_id']??0);$items=$d['items']??[];$q=$pdo->prepare('SELECT status FROM procurement_batches WHERE id=?');$q->execute([$id]);if(!$q->fetchColumn())json_response(['status'=>'error','message'=>'ไม่พบรอบจัดซื้อ'],404);foreach($items as $i){$pdo->prepare("UPDATE procurement_batch_items SET quantity_received=? WHERE id=?")->execute([(float)$i['quantity_received'],(int)$i['id']]);}$q=$pdo->prepare('SELECT SUM(quantity_ordered),SUM(quantity_received) FROM procurement_batch_items WHERE batch_id=?');$q->execute([$id]);[$ordered,$received]=$q->fetch(PDO::FETCH_NUM);$status=$received<=0?'ordered':($received<$ordered?'received_partial':'received_complete');$pdo->prepare('UPDATE procurement_batches SET status=?,received_date=IF(?="received_complete",CURDATE(),received_date) WHERE id=?')->execute([$status,$status,$id]);json_response(['status'=>'success','message'=>'บันทึกการรับสินค้าเข้ารอบแล้ว']);}
 if($action==='announce'){$d=json_input();$id=(int)($d['batch_id']??$_GET['batch_id']??0);$text=trim((string)($d['announcement_text']??''));if(!$id)json_response(['status'=>'error','message'=>'ไม่พบรอบจัดซื้อที่ต้องการประกาศ'],422);if($text==='')$text='สินค้าตามรอบจัดซื้อพร้อมให้สมาชิกมารับที่สำนักงานกองทุนหมู่บ้าน';$q=$pdo->prepare('SELECT status FROM procurement_batches WHERE id=?');$q->execute([$id]);$status=$q->fetchColumn();if($status===false)json_response(['status'=>'error','message'=>'ไม่พบรอบจัดซื้อ'],404);if(!in_array($status,['received_complete','announced'],true))json_response(['status'=>'error','message'=>'ยังไม่สามารถประกาศได้ ต้องตรวจรับสินค้าให้ครบก่อน'],409);$pdo->prepare("UPDATE procurement_batches SET status='announced',announcement_text=? WHERE id=?")->execute([$text,$id]);json_response(['status'=>'success','message'=>'ประกาศพร้อมรับสินค้าแล้ว']);}
 if($action==='member_deliveries'){ require_role(['member']); $q=$pdo->prepare("SELECT pd.id,pd.delivery_status,pd.delivery_date,pd.receipt_number,b.batch_no,b.title AS batch_title,b.announcement_text,r.id AS request_id,r.amount_requested FROM product_deliveries pd JOIN procurement_batches b ON b.id=pd.batch_id JOIN requests r ON r.id=pd.request_id WHERE pd.member_id=? ORDER BY pd.id DESC"); $q->execute([(int)$user['id']]); json_response(['status'=>'success','data'=>$q->fetchAll()]); }
 if($action==='receiving_detail'){ $id=(int)($_GET['batch_id']??0); $q=$pdo->prepare("SELECT b.*,pr.id AS receipt_id,pr.status AS receipt_status,pr.inspected_at,pr.received_note,pr.rejection_note FROM procurement_batches b LEFT JOIN procurement_receipts pr ON pr.batch_id=b.id WHERE b.id=?"); $q->execute([$id]); $batch=$q->fetch(); if(!$batch) json_response(['status'=>'error','message'=>'ไม่พบรอบจัดซื้อ'],404); $q=$pdo->prepare("SELECT pbi.*,COALESCE(pri.quantity_counted,0) quantity_counted,COALESCE(pri.condition_status,'good') condition_status,COALESCE(pri.note,'') receipt_note FROM procurement_batch_items pbi LEFT JOIN procurement_receipts pr ON pr.batch_id=pbi.batch_id LEFT JOIN procurement_receipt_items pri ON pri.receipt_id=pr.id AND pri.batch_item_id=pbi.id WHERE pbi.batch_id=? ORDER BY pbi.item_name_snapshot"); $q->execute([$id]); $batch['items']=$q->fetchAll(); json_response(['status'=>'success','data'=>$batch]); }
 if($action==='inspect_receiving'){ $d=json_input(); $id=(int)($d['batch_id']??0); $items=$d['items']??[]; if(!$id||!is_array($items)||!count($items)) json_response(['status'=>'error','message'=>'กรุณาตรวจสอบรายการสินค้า'],422); $pdo->beginTransaction(); $q=$pdo->prepare("INSERT INTO procurement_receipts(batch_id,status,inspected_by,inspected_at,received_note,rejection_note) VALUES(?, 'pending', ?, NOW(), ?, ?) ON DUPLICATE KEY UPDATE inspected_by=VALUES(inspected_by), inspected_at=NOW(), received_note=VALUES(received_note), rejection_note=VALUES(rejection_note)"); $q->execute([$id,$user['id'],$d['received_note']??null,$d['rejection_note']??null]); $rid=(int)$pdo->lastInsertId(); if(!$rid){$q=$pdo->prepare('SELECT id FROM procurement_receipts WHERE batch_id=?');$q->execute([$id]);$rid=(int)$q->fetchColumn();} $pdo->prepare('DELETE FROM procurement_receipt_items WHERE receipt_id=?')->execute([$rid]); $allGood=true;$allQty=true; foreach($items as $i){$expected=(float)($i['quantity_expected']??0);$counted=(float)($i['quantity_counted']??0);$condition=$i['condition_status']??'good'; if($condition!=='good')$allGood=false;if($counted<$expected)$allQty=false;$pdo->prepare('INSERT INTO procurement_receipt_items(receipt_id,batch_item_id,quantity_expected,quantity_counted,condition_status,note) VALUES(?,?,?,?,?,?)')->execute([$rid,(int)$i['batch_item_id'],$expected,$counted,$condition,$i['note']??null]); $pdo->prepare('UPDATE procurement_batch_items SET quantity_received=? WHERE id=?')->execute([$counted,(int)$i['batch_item_id']]);} $status=$allGood&&$allQty?'accepted':'partial';$pdo->prepare('UPDATE procurement_receipts SET status=? WHERE id=?')->execute([$status,$rid]); $batchStatus=$allGood&&$allQty?'received_complete':'received_partial';$pdo->prepare('UPDATE procurement_batches SET status=?,received_date=IF(?="received_complete",CURDATE(),received_date) WHERE id=?')->execute([$batchStatus,$batchStatus,$id]);$pdo->commit();json_response(['status'=>'success','message'=>$status==='accepted'?'ตรวจรับสินค้าเรียบร้อย สินค้าครบและสภาพปกติ':'บันทึกผลการตรวจรับแล้ว มีรายการที่ต้องติดตาม']); }
 if($action==='deliveries'){$id=(int)($_GET['batch_id']??0);$q=$pdo->prepare("SELECT pd.*,m.fullname,m.username FROM product_deliveries pd JOIN members m ON m.id=pd.member_id WHERE pd.batch_id=? ORDER BY pd.delivery_status,m.fullname");$q->execute([$id]);json_response(['status'=>'success','data'=>$q->fetchAll()]);}
 if($action==='prepare_deliveries'){ $d=json_input(); $id=(int)($d['batch_id']??$_GET['batch_id']??0); if(!$id)json_response(['status'=>'error','message'=>'ไม่พบรอบจัดซื้อที่ต้องการเตรียมรายการ'],422); $q=$pdo->prepare("SELECT status FROM procurement_batches WHERE id=?");$q->execute([$id]);$status=$q->fetchColumn();if(!$status)json_response(['status'=>'error','message'=>'ไม่พบรอบจัดซื้อ'],404);if(!in_array($status,['received_complete','announced'],true))json_response(['status'=>'error','message'=>'ต้องตรวจรับสินค้าให้ครบก่อนจึงเตรียมรายการสมาชิกได้'],409);$q=$pdo->prepare("SELECT pri.request_id,r.member_id FROM procurement_request_items pri JOIN requests r ON r.id=pri.request_id WHERE pri.batch_id=? GROUP BY pri.request_id,r.member_id");$q->execute([$id]);$count=0;foreach($q as $x){$s=$pdo->prepare("INSERT IGNORE INTO product_deliveries(batch_id,request_id,member_id,delivery_status) VALUES(?,?,?,'ready')");$s->execute([$id,$x['request_id'],$x['member_id']]);$count+=$s->rowCount();}$pdo->prepare("UPDATE procurement_batches SET status='announced' WHERE id=? AND status='received_complete'")->execute([$id]);json_response(['status'=>'success','message'=>$count?'เตรียมรายการรับสินค้าให้สมาชิกแล้ว':'รายการสมาชิกถูกเตรียมไว้แล้ว','count'=>$count]);}
 if($action==='deliver'){$d=json_input();$id=(int)($d['delivery_id']??0);$name=trim((string)($d['received_by_name']??''));if($name==='')json_response(['status'=>'error','message'=>'กรุณาระบุชื่อผู้รับสินค้า'],422);$pdo->prepare("UPDATE product_deliveries SET delivery_status='delivered',delivery_date=NOW(),received_by_name=?,received_by_national_id=?,received_as=?,representative_relation=?,delivered_by=?,note=? WHERE id=?")->execute([$name,$d['received_by_national_id']??null,($d['received_as']??'member')==='representative'?'representative':'member',$d['representative_relation']??null,$user['id'],$d['note']??null,$id]);$receipt='RC-'.date('Ymd').'-'.str_pad((string)$id,5,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE product_deliveries SET receipt_number=? WHERE id=?')->execute([$receipt,$id]);json_response(['status'=>'success','message'=>'บันทึกการส่งมอบสินค้าแล้ว','receipt_number'=>$receipt]);}
 json_response(['status'=>'error','message'=>'ไม่พบคำสั่ง'],400);
}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());$msg=$e->getCode()==='42S02'?'ยังไม่ได้ติดตั้งตารางตรวจรับสินค้า กรุณารัน database/run_migration_v4.bat':($e->getCode()==='23000'?'ข้อมูลตรวจรับซ้ำหรือไม่สัมพันธ์กับรอบจัดซื้อ':'ไม่สามารถบันทึกผลตรวจรับสินค้าได้ กรุณาตรวจสอบข้อมูล');json_response(['status'=>'error','message'=>$msg],400);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());json_response(['status'=>'error','message'=>'เกิดข้อผิดพลาดของระบบ'],500);}
